export function defaultRunAction(
    action: ActionDefinition,
    context: ActionContext,
    input?: ActionRunInput,
    onStarted?: (executionId: string) => void,
) {
    return runElectronAction(action, context, input, onStarted)
}

export function defaultLoadHistory(action: ActionDefinition, context: ActionContext) {
    return loadActionHistory({
        action,
        actionHistoryLoader: defaultActionHistoryLoader,
        bridge: getElectronActionBridge(),
        context,
    })
}

export function defaultLoadConversation(path: string) {
    return dataService.loadAgentConversation(path)
}

export function defaultLoadConversations(context: ActionContext) {
    return dataService.listAgentConversations(context)
}

export async function defaultPreparePrompt(action: ActionDefinition, context: ActionContext) {
    const bridge = getElectronActionBridge()
    if (!bridge) throw new Error('Preparing action prompts requires the Electron desktop app')
    flushMarkdownEditors()
    if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()
    const result = await bridge.prepareActionPrompt({ actionId: action.id, context })

    return result.prompt
}

export async function defaultConvertPromptToAction(input: ConvertPromptToActionInput) {
    const actionsFolder = dataService.getConfig()?.actionsFolder
    if (!actionsFolder) throw new Error('Cannot convert prompt before project config is loaded')

    const definition = createActionDefinition(input)
    const path = actionFilePath(actionsFolder, definition.label)
    await dataService.cards.saveProjectFile({ content: `${JSON.stringify(definition, null, 2)}\n`, path }, `Create ${path}`)

    return { definition, path }
}

export function defaultCancelAction(executionId: string) {
    return cancelElectronAction(executionId)
}

export function defaultSendMessage(executionId: string, content: string) {
    return sendActionMessage(executionId, content)
}

export function defaultFinishAction(executionId: string) {
    return finishActionExecution(executionId)
}

export function defaultAnswerQuestion(
    executionId: string,
    requestId: number | string | null,
    answers: Record<string, string[]>,
) {
    return answerActionQuestion(executionId, requestId, answers)
}

export async function defaultScheduleAction(action: ActionDefinition, context: ActionContext, trigger: ActionScheduleTrigger) {
    const bridge = getElectronActionBridge()
    if (!bridge?.registerActionSchedule) throw new Error('Scheduling actions requires Electron local mode')

    await bridge.registerActionSchedule({ actionId: action.id, context, trigger })
}

export function statusColor(status: PopupRunStatus) {
    if (status === 'completed') return 'success.main'
    if (status === 'failed') return 'error.main'
    if (status === 'running' || status === 'waitingForInput') return 'info.main'
    if (status === 'okButNotAfter' || status === 'cancelled') return 'warning.main'

    return 'text.secondary'
}

import { useSyncExternalStore } from 'react'
import type { ActionContext } from '../../data/action_context'
import { actionExecutionService } from '../../services/actions/action_execution_service'

function useActionExecutionSnapshot() {
    return useSyncExternalStore(
        (listener) => {
            actionExecutionService.addEventListener('changed', listener)

            return () => actionExecutionService.removeEventListener('changed', listener)
        },
        () => actionExecutionService.getSnapshot(),
        () => actionExecutionService.getSnapshot(),
    )
}

function useRunningActionExecutionSnapshot() {
    return useSyncExternalStore(
        (listener) => {
            actionExecutionService.addEventListener('runningChanged', listener)

            return () => actionExecutionService.removeEventListener('runningChanged', listener)
        },
        () => actionExecutionService.getRunningSnapshot(),
        () => actionExecutionService.getRunningSnapshot(),
    )
}

function subscribeToRunningActionChanges(listener: () => void) {
    actionExecutionService.addEventListener('runningChanged', listener)

    return () => actionExecutionService.removeEventListener('runningChanged', listener)
}

function useRunningActionExecutionId(getExecutionId: () => string | null) {
    return useSyncExternalStore(subscribeToRunningActionChanges, getExecutionId, getExecutionId)
}

export function useActionExecution(actionId: string, context: ActionContext) {
    useActionExecutionSnapshot()

    return actionExecutionService.getExecution(actionId, context)
}

export function useRunningActionForContext(context: ActionContext) {
    const getExecutionId = () => actionExecutionService.getRunningExecutionForContext(context)?.executionId ?? null
    const executionId = useRunningActionExecutionId(getExecutionId)
    if (!executionId) return null

    return actionExecutionService.getRunningExecutionForContext(context)
}

export function useRunningActionForFile(filePath: string | null) {
    const getExecutionId = () => actionExecutionService.getRunningExecutionForFile(filePath)?.executionId ?? null
    const executionId = useRunningActionExecutionId(getExecutionId)
    if (!executionId) return null

    return actionExecutionService.getRunningExecutionForFile(filePath)
}

export function useActionExecutions() {
    return useActionExecutionSnapshot().executions
}

export function useRunningActionExecutions() {
    return useRunningActionExecutionSnapshot()
}

import type { ProjectCard } from '../../data/data_types'
import { hasUnseenAgentResult } from './agent_acknowledgement_service'

export type CardAgentState = 'idle' | 'running' | 'unseen result' | 'waiting for input'

function isConversationWaiting(card: ProjectCard) {
    return card.agentConversations.some((conversation) => {
        if (conversation.status === 'waitingForInput') return true
        if (conversation.status !== 'running') return false

        const stateEvent = [...conversation.events].reverse().find((event) => event.type === 'waiting' || event.type === 'resumed')

        return stateEvent?.type === 'waiting'
    })
}

/** True when the card has at least one agent conversation still running. */
export function hasRunningConversation(card: ProjectCard) {
    return card.agentConversations.some((conversation) => (
        conversation.status === 'running' || conversation.status === 'waitingForInput'
    ))
}

/** Resolve the single agent state shown for a card, mirroring the priority waiting > running > unseen > idle. */
export function cardAgentState(projectKey: string, card: ProjectCard): CardAgentState {
    if (isConversationWaiting(card)) return 'waiting for input'
    if (hasRunningConversation(card)) return 'running'
    if (hasUnseenAgentResult(projectKey, card.path, card.agentConversations)) return 'unseen result'

    return 'idle'
}

/** Human-readable description of an agent state, or null when idle. */
export function agentStateDescription(agentState: CardAgentState): string | null {
    if (agentState === 'waiting for input') return 'Agent is waiting for input'
    if (agentState === 'running') return 'Agent is running'
    if (agentState === 'unseen result') return 'New agent result available'

    return null
}

const AGENT_MESSAGE_ROLES = new Set(['assistant', 'user'])
const AGENT_STATUSES = new Set(['cancelled', 'completed', 'failed', 'running', 'waitingForInput'])

function requiredString(value, fieldName) {
    if (typeof value !== 'string' || value.length === 0) throw new Error(`Malformed agent conversation: missing ${fieldName}`)

    return value
}

function optionalString(value) {
    return typeof value === 'string' && value.length > 0 ? value : null
}

function usageNumber(value) {
    return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : 0
}

function normalizeUsage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined

    const usage = {
        cachedInputTokens: usageNumber(value.cachedInputTokens),
        inputTokens: usageNumber(value.inputTokens),
        outputTokens: usageNumber(value.outputTokens),
        reasoningTokens: usageNumber(value.reasoningTokens),
    }
    usage.totalTokens = usage.inputTokens + usage.cachedInputTokens + usage.outputTokens + usage.reasoningTokens
    if (typeof value.costUsd === 'number' && Number.isFinite(value.costUsd) && value.costUsd >= 0) usage.costUsd = value.costUsd

    return usage
}

function normalizeMessage(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    if (!AGENT_MESSAGE_ROLES.has(value.role)) return null
    if (typeof value.content !== 'string') return null
    const id = optionalString(value.id)
    const timestamp = optionalString(value.timestamp)
    if (!id || !timestamp) return null
    const agent = optionalString(value.agent)

    return { ...(agent ? { agent } : {}), content: value.content, id, role: value.role, timestamp }
}

function normalizeEvent(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    if (typeof value.content !== 'string') return null
    const id = optionalString(value.id)
    const timestamp = optionalString(value.timestamp)
    const type = optionalString(value.type)
    if (!id || !timestamp || !type) return null

    return { content: value.content, id, timestamp, type }
}

function normalizeProviderSession(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null
    const agent = optionalString(value.agent)
    const conversationId = optionalString(value.conversationId)
    const createdAt = optionalString(value.createdAt)
    const lastUsedAt = optionalString(value.lastUsedAt)
    const synchronizedThroughMessageId = optionalString(value.synchronizedThroughMessageId)
    if (!agent || !conversationId || !createdAt || !lastUsedAt || !synchronizedThroughMessageId) return null

    return { agent, conversationId, createdAt, lastUsedAt, synchronizedThroughMessageId }
}

function normalizeArray(value, normalize) {
    if (!Array.isArray(value)) return []

    return value.map(normalize).filter((entry) => entry !== null)
}

/** Parse one canonical conversation record while discarding malformed optional entries. */
export function parseAgentConversation(content, referencePath) {
    const parsed = JSON.parse(content)
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('Malformed agent conversation: root must be an object')
    const id = requiredString(parsed.id, 'id')
    const status = requiredString(parsed.status, 'status')
    if (!AGENT_STATUSES.has(status)) throw new Error(`Malformed agent conversation: invalid status ${status}`)
    const startedAt = requiredString(parsed.startedAt, 'startedAt')
    const hasExplicitTitle = typeof parsed.title === 'string' && parsed.title.trim().length > 0
    const usage = normalizeUsage(parsed.usage)

    return {
        actionId: optionalString(parsed.actionId),
        cardInternalId: optionalString(parsed.cardInternalId),
        cardPath: optionalString(parsed.cardPath),
        completedAt: optionalString(parsed.completedAt),
        events: normalizeArray(parsed.events, normalizeEvent),
        hasExplicitTitle,
        id,
        messages: normalizeArray(parsed.messages, normalizeMessage),
        path: referencePath,
        providerSessions: normalizeArray(parsed.providerSessions, normalizeProviderSession),
        startedAt,
        status,
        title: hasExplicitTitle ? parsed.title : id,
        ...(usage ? { usage } : {}),
    }
}

import { Box, IconButton, ToggleButton, ToggleButtonGroup, Tooltip } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import Play from 'mdi-material-ui/Play'
import Plus from 'mdi-material-ui/Plus'
import type { MouseEvent } from 'react'
