import type { AgentConversation } from '../../data/data_types'
import { useActions } from '../hooks/use_actions'
import { useRunningActionExecutions } from '../hooks/use_action_executions'
import { useProjectState } from '../hooks/use_project_state'
import { useProjectActionWorktree } from '../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    onClose: () => void
    onConversationViewed?: (conversation: AgentConversation) => void
    open?: boolean
    unseenResultActionIds?: string[]
}

/** Universal action selector and execution popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, open } = props
    const { actions: loadedActions } = useActions()
    const runningExecutions = useRunningActionExecutions()
    const { project } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const contextIdentity = actionContextIdentity(context)
    const runningActionIds = [...new Set(runningExecutions
        .filter((execution) => actionContextIdentity(execution.context) === contextIdentity)
        .map((execution) => execution.rootActionId))]
    const [selectedActionId, setSelectedActionId] = useState<string | null>(initialActionId ?? actions[0]?.id ?? null)
    const [showSaveControls, setShowSaveControls] = useState(false)
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
        setShowSaveControls(false)
    }

    const handleAddAction = () => {
        const customPrompt = actions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
        if (!customPrompt) throw new Error('Missing custom prompt action')

        setSelectedActionId(customPrompt.id)
        setShowSaveControls((current) => !current)
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            onAddAction={handleAddAction}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            runningActionIds={runningActionIds}
            showSaveControls={showSaveControls}
            titleId={titleId}
        />
    )
}

import { useSyncExternalStore } from 'react'
import {
    cardActionPopupService,
    subscribeCardActionPopups,
} from '../../services/actions/card_action_popup_service'
import { CardActionPopupHostEntry } from './card_action_popup_host_entry'

/** Stable renderer for all service-owned card action popups. */
export function CardActionPopupHost() {
    const entries = useSyncExternalStore(
        subscribeCardActionPopups,
        () => cardActionPopupService.getSnapshot(),
        () => cardActionPopupService.getSnapshot(),
    )

    return entries.map((entry) => <CardActionPopupHostEntry entry={entry} key={entry.id} />)
}

import { actionContextIdentity, type ActionContext } from '../../data/action_context'
import type { DataService } from '../data/data_service'
import { dataService } from '../data/data_service'
import { register } from '../service_injector'

const CARD_ACTION_POPUPS_CHANGED_EVENT = 'changed'

export interface CardActionPopupEntry {
    anchorElement: HTMLElement
    context: ActionContext
    fallbackAnchorElement: HTMLElement
    id: string
    projectKey: string
    unseenResultActionIds: string[]
}

function projectKey(service: DataService) {
    const project = service.getState().project

    return project ? `${project.id}:${project.branch}` : null
}

function createFallbackAnchor(anchorElement: HTMLElement) {
    const bounds = anchorElement.getBoundingClientRect()
    const fallbackAnchorElement = document.createElement('span')
    fallbackAnchorElement.setAttribute('aria-hidden', 'true')
    fallbackAnchorElement.dataset.cardActionPopupAnchor = 'true'
    Object.assign(fallbackAnchorElement.style, {
        height: `${bounds.height}px`,
        left: `${bounds.left}px`,
        pointerEvents: 'none',
        position: 'fixed',
        top: `${bounds.top}px`,
        visibility: 'hidden',
        width: `${bounds.width}px`,
    })
    document.body.append(fallbackAnchorElement)

    return fallbackAnchorElement
}

/** Owns every open card action popup independently from card component lifetimes. */
export class CardActionPopupService extends EventTarget {
    private readonly dataService: DataService
    private entries: CardActionPopupEntry[] = []
    private nextId = 1
    private currentProjectKey: string | null

    constructor(dataServiceInstance: DataService) {
        super()
        this.dataService = dataServiceInstance
        this.currentProjectKey = projectKey(this.dataService)
        this.dataService.addEventListener('changed', this.handleDataServiceChanged)
    }

    getSnapshot() {
        return this.entries
    }

    toggle(context: ActionContext, anchorElement: HTMLElement, activeProjectKey: string, unseenResultActionIds: string[]) {
        const contextIdentity = actionContextIdentity(context)
        const existing = this.entries.find((entry) => actionContextIdentity(entry.context) === contextIdentity)
        if (existing) {
            this.close(existing.id)
            return
        }

        if (!context.cardInternalId) throw new Error('Cannot open a card action popup without a card internal ID')

        const entry = {
            anchorElement,
            context: { ...context },
            fallbackAnchorElement: createFallbackAnchor(anchorElement),
            id: `card-action-popup-${this.nextId}`,
            projectKey: activeProjectKey,
            unseenResultActionIds: [...unseenResultActionIds],
        }
        this.nextId += 1
        this.setEntries([...this.entries, entry])
    }

    close(id: string) {
        const entry = this.entries.find((candidate) => candidate.id === id)
        if (!entry) return

        entry.fallbackAnchorElement.remove()
        this.setEntries(this.entries.filter((candidate) => candidate.id !== id))
    }

    clear() {
        if (this.entries.length === 0) return

        this.entries.forEach(({ fallbackAnchorElement }) => fallbackAnchorElement.remove())
        this.setEntries([])
    }

    private readonly handleDataServiceChanged = () => {
        const nextProjectKey = projectKey(this.dataService)
        if (nextProjectKey === this.currentProjectKey) return

        this.currentProjectKey = nextProjectKey
        this.clear()
    }

    private setEntries(entries: CardActionPopupEntry[]) {
        this.entries = entries
        this.dispatchEvent(new Event(CARD_ACTION_POPUPS_CHANGED_EVENT))
    }
}

export const cardActionPopupService = register('cardActionPopupService', new CardActionPopupService(dataService))

export function subscribeCardActionPopups(onStoreChange: () => void) {
    cardActionPopupService.addEventListener(CARD_ACTION_POPUPS_CHANGED_EVENT, onStoreChange)

    return () => cardActionPopupService.removeEventListener(CARD_ACTION_POPUPS_CHANGED_EVENT, onStoreChange)
}

