                {showAgentSend ? (
                    <Tooltip title="Send">
                        <span>
                            <IconButton
                                aria-label="Send"
                                color="primary"
                                disabled={runDisabled}
                                onClick={handlePrimaryRun}
                                size="small"
                            >
                                <ArrowUpwardOutlined sx={{ fontSize: 18 }} />
                            </IconButton>
                        </span>
                    </Tooltip>
                ) : showCommandRun ? (
                    <Button
                        disabled={runDisabled}
                        onClick={handlePrimaryRun}
                        size="small"
                        startIcon={<Play sx={{ fontSize: '13px !important' }} />}
                        sx={{ height: 34, px: 2 }}
                        variant="contained"
                    >
